namespace {
    namespace FS = std::filesystem;

    constexpr std::string_view kVersion = "0.1.0";

    struct DefineOperation {
        enum class Type {
            Define,
            Undefine
        };

        Type Operation;
        std::string Name;
        std::string Value;
    };

    struct Options {
        FS::path Input;
        FS::path Output;
        std::vector<FS::path> ImportPaths;
        std::vector<DefineOperation> DefineOperations;

        bool Debug = false;
        bool Verbose = false;
        bool ShowHelp = false;
        bool ShowVersion = false;
        bool Optimize = true;
    };

    void PrintUsage(std::ostream& stream) {
        stream << "Usage: ce_scriptc [OPTIONS] [FILE]\n"
               << "       ce_scriptc [COMMAND] [OPTIONS] FILE\n\n"
               << "Commands:\n"
               << "  compile            Compile an AngelScript file\n"
               << "  build              Alias for compile\n"
               << "  help               Show this help message\n"
               << "  version            Show compiler version\n\n"
               << "Compile AngelScript source into CEBYC bytecode.\n\n"
               << "Options:\n"
               << "  -h, --help          Show this help message\n"
               << "  -V, --version       Show compiler version\n"
               << "  -o FILE             Set output file\n"
               << "  -g, --debug         Include debug information\n"
               << "  -I DIR              Add an import search directory\n"
               << "  -D NAME[=VALUE]     Define a preprocessor macro\n"
               << "  -U NAME             Remove a preprocessor macro\n"
               << "  -v, --verbose       Enable verbose output\n"
               << "  -O0                 Disable bytecode optimization\n"
               << "  -O1                 Enable bytecode optimization\n"
               << "  --                  Treat remaining arguments as positional\n";
    }

    void PrintVersion() {
        std::cout << "ce_scriptc " << kVersion << '\n'
                  << "AngelScript version: " << asGetLibraryVersion() << '\n';
    }

    bool IsIdentifier(std::string_view name) {
        if (name.empty()) {
            return false;
        }

        const auto is_first = [](unsigned char c) {
            return (c >= 'a' && c <= 'z') ||
                   (c >= 'A' && c <= 'Z') ||
                   c == '_';
        };

        const auto is_rest = [&](unsigned char c) {
            return is_first(c) || (c >= '0' && c <= '9');
        };

        if (!is_first(static_cast<unsigned char>(name.front()))) {
            return false;
        }

        for (size_t i = 1; i < name.size(); ++i) {
            if (!is_rest(static_cast<unsigned char>(name[i]))) {
                return false;
            }
        }

        return true;
    }

    bool ParseDefineOperation(std::string_view argument, bool undefine, Options& options) {
        const size_t equals = argument.find('=');
        const std::string_view name = argument.substr(0, equals);

        if (!IsIdentifier(name)) {
            std::cerr << "ce_scriptc: invalid macro name: '" << name << "'\n";
            return false;
        }

        if (undefine && equals != std::string_view::npos) {
            std::cerr << "ce_scriptc: -U does not accept a value\n";
            return false;
        }

        std::string value = "1";

        if (!undefine && equals != std::string_view::npos) {
            value = std::string(argument.substr(equals + 1));
        }

        options.DefineOperations.push_back({
            undefine ? DefineOperation::Type::Undefine : DefineOperation::Type::Define,
            std::string(name),
            std::move(value)
        });

        return true;
    }

    bool ParseArguments(int argc, char* argv[], Options& options) {
        std::vector<std::string> positional;
        bool parse_options = true;

        for (int i = 1; i < argc; ++i) {
            const std::string_view arg(argv[i]);

            if (parse_options && arg == "--") {
                parse_options = false;
                continue;
            }

            if (parse_options && (arg == "compile" || arg == "build") && positional.empty()) {
                continue;
            }

            if (parse_options && (arg == "help" || arg == "version")) {
                if (arg == "help") {
                    options.ShowHelp = true;
                } else {
                    options.ShowVersion = true;
                }

                continue;
            }

            if (parse_options && (arg == "-h" || arg == "--help")) {
                options.ShowHelp = true;
                continue;
            }

            if (parse_options && (arg == "-V" || arg == "--version")) {
                options.ShowVersion = true;
                continue;
            }

            if (parse_options && (arg == "-g" || arg == "--debug")) {
                options.Debug = true;
                continue;
            }

            if (parse_options && (arg == "-v" || arg == "--verbose")) {
                options.Verbose = true;
                continue;
            }

            if (parse_options && arg == "-O0") {
                options.Optimize = false;
                continue;
            }

            if (parse_options && arg == "-O1") {
                options.Optimize = true;
                continue;
            }

            if (parse_options && arg == "-o") {
                if (++i >= argc) {
                    std::cerr << "ce_scriptc: option '-o' requires an argument\n";
                    return false;
                }

                options.Output = argv[i];
                continue;
            }

            if (parse_options && arg == "-I") {
                if (++i >= argc) {
                    std::cerr << "ce_scriptc: option '-I' requires an argument\n";
                    return false;
                }

                options.ImportPaths.emplace_back(argv[i]);
                continue;
            }

            if (parse_options && (arg == "-D" || arg == "-U")) {
                const bool undefine = arg == "-U";

                if (++i >= argc) {
                    std::cerr << "ce_scriptc: option '" << arg << "' requires an argument\n";
                    return false;
                }

                if (!ParseDefineOperation(argv[i], undefine, options)) {
                    return false;
                }

                continue;
            }

            if (parse_options && arg.starts_with("-D") && arg.size() > 2) {
                if (!ParseDefineOperation(arg.substr(2), false, options)) {
                    return false;
                }

                continue;
            }

            if (parse_options && arg.starts_with("-U") && arg.size() > 2) {
                if (!ParseDefineOperation(arg.substr(2), true, options)) {
                    return false;
                }

                continue;
            }

            if (parse_options && arg.starts_with("-I") && arg.size() > 2) {
                options.ImportPaths.emplace_back(std::string(arg.substr(2)));
                continue;
            }

            if (parse_options && !arg.empty() && arg.front() == '-') {
                std::cerr << "ce_scriptc: unknown option '" << arg << "'\n";
                return false;
            }

            positional.emplace_back(arg);
        }

        if (options.ShowHelp || options.ShowVersion) {
            return true;
        }

        if (positional.size() != 1) {
            std::cerr << "ce_scriptc: expected exactly one input file\n";
            return false;
        }

        options.Input = positional.front();

        if (options.Output.empty()) {
            options.Output = options.Input;
            options.Output.replace_extension(".cebyc");
        }

        return true;
    }

    void MessageCallback(const asSMessageInfo* message, void*) {
        const char* section = message->section != nullptr ? message->section : "<unknown>";

        const char* type = "info";

        if (message->type == asMSGTYPE_WARNING) {
            type = "warning";
        } else if (message->type == asMSGTYPE_ERROR) {
            type = "error";
        }

        std::cerr << section << ':' << message->row << ':' << message->col
                  << ": " << type << ": " << message->message << '\n';
    }

    void RegisterAddons(asIScriptEngine* engine) {
        RegisterScriptArray(engine, true);
        RegisterStdString(engine);
        RegisterStdStringUtils(engine);
        RegisterScriptDictionary(engine);
        RegisterScriptAny(engine);
        RegisterScriptGrid(engine);
        RegisterScriptHandle(engine);
        RegisterScriptMath(engine);
        RegisterScriptDateTime(engine);
    }

    void ApplyEngineProperties(asIScriptEngine* engine, const Options& options) {
        engine->SetEngineProperty(asEP_OPTIMIZE_BYTECODE, options.Optimize ? 1 : 0);
        engine->SetEngineProperty(asEP_INIT_GLOBAL_VARS_AFTER_BUILD, false);
    }

    int Compile(const Options& options) {
        if (!FS::exists(options.Input) || !FS::is_regular_file(options.Input)) {
            std::cerr << "ce_scriptc: input file does not exist or is not a regular file: "
                      << options.Input.string() << '\n';
            return 1;
        }

        if (options.Verbose) {
            std::cout << "Input:  " << options.Input.string() << '\n'
                      << "Output: " << options.Output.string() << '\n';
        }

        std::vector<FS::path> import_paths = options.ImportPaths;

        if (import_paths.empty()) {
            import_paths.push_back(
                options.Input.parent_path().empty()
                    ? FS::current_path()
                    : options.Input.parent_path()
            );
        }

        // Configure the preprocessor before loading any modules.
        CE::Scripting::Impl::Preprocessor preprocessor;

        for (const auto& operation : options.DefineOperations) {
            if (operation.Operation == DefineOperation::Type::Undefine) {
                // Undefining an unknown macro is harmless.
                preprocessor.RemoveDefine(operation.Name);
                continue;
            }

            if (!preprocessor.AddDefine({operation.Name, operation.Value})) {
                std::cerr << "ce_scriptc: failed to define macro '"
                          << operation.Name << "'\n";
                return 1;
            }
        }

        if (options.Verbose) {
            std::cout << "Configured " << options.DefineOperations.size()
                      << " preprocessor operation(s)\n";

            for (const auto& operation : options.DefineOperations) {
                if (operation.Operation == DefineOperation::Type::Define) {
                    std::cout << "  define " << operation.Name << '='
                              << operation.Value << '\n';
                } else {
                    std::cout << "  undefine " << operation.Name << '\n';
                }
            }
        }

        // The importer and semantic analyser share this preprocessor.
        CE::Scripting::Impl::ModuleImporter importer(import_paths, preprocessor);

        std::vector<CE::Scripting::Impl::GeneratedScriptSection> sections;

        try {
            sections = importer.LoadFile(options.Input.filename().string());
        } catch (const std::exception& exception) {
            std::cerr << "ce_scriptc: failed to load scripts: "
                      << exception.what() << '\n';
            return 1;
        }

        if (sections.empty()) {
            std::cerr << "ce_scriptc: no script sections were generated\n";
            return 1;
        }

        if (options.Verbose) {
            std::cout << "Generated " << sections.size() << " script section(s)\n";
        }

        // Create the AngelScript engine.
        asIScriptEngine* engine = asCreateScriptEngine();

        if (engine == nullptr) {
            std::cerr << "ce_scriptc: failed to create AngelScript engine\n";
            return 1;
        }

        engine->SetMessageCallback(asFUNCTION(MessageCallback), nullptr, asCALL_CDECL);

        // Engine properties first, since they can affect registration.
        ApplyEngineProperties(engine, options);

        RegisterAddons(engine);

        engine->SetDefaultNamespace("CE::Containers");
        CEScriptC::RegisterVector<asUINT>(engine, "Uint32Vector", "uint32");
        engine->SetDefaultNamespace("");

        engine->SetDefaultNamespace("CE::Input::Keyboard");
        CE::Scripting::Bindings::RegisterKeyboardEnum(engine);
        engine->SetDefaultNamespace("");

        if (!CE::Scripting::Bindings::RegisterSubscribeEventFuncDef(*engine)) {
            std::cerr << "ce_scriptc: failed to register event subscription function\n";
            engine->ShutDownAndRelease();
            return 1;
        }

        if (engine->RegisterObjectType(
                "__ce_void_ptr",
                sizeof(void*),
                asOBJ_VALUE | asOBJ_POD | asOBJ_APP_PRIMITIVE) < 0) {
            CE_LOG(CECommon::LogLevel::Error, "[Angelscript] Failed to register __ce_void_ptr");
            engine->ShutDownAndRelease();
            return 1;
        }

        engine->SetDefaultNamespace("CE");

        if (!RegisterDummyBindings(engine)) {
            std::cerr << "ce_scriptc: failed to register dummy bindings\n";
            engine->ShutDownAndRelease();
            return 1;
        }

        if (options.Verbose) {
            std::cout << "Registered add-ons and dummy bindings\n";
        }

        asIScriptModule* module = engine->GetModule("ce_scriptc", asGM_ALWAYS_CREATE);

        if (module == nullptr) {
            std::cerr << "ce_scriptc: failed to create script module\n";
            engine->ShutDownAndRelease();
            return 1;
        }

        for (const auto& section : sections) {
            const int result = module->AddScriptSection(
                section.Name.c_str(),
                section.Code.data(),
                section.Code.size()
            );

            if (result < 0) {
                std::cerr << "ce_scriptc: failed to add script section '"
                          << section.Name << "'\n";
                engine->ShutDownAndRelease();
                return 1;
            }
        }

        if (options.Verbose) {
            std::cout << "Building AngelScript module...\n";
        }

        const int build_result = module->Build();

        if (build_result < 0) {
            std::cerr << "ce_scriptc: compilation failed\n";
            engine->ShutDownAndRelease();
            return 1;
        }

        // Create the output directory if necessary.
        std::error_code filesystem_error;

        if (!options.Output.parent_path().empty()) {
            FS::create_directories(options.Output.parent_path(), filesystem_error);

            if (filesystem_error) {
                std::cerr << "ce_scriptc: failed to create output directory: "
                          << filesystem_error.message() << '\n';
                engine->ShutDownAndRelease();
                return 1;
            }
        }

        // Serialize bytecode, entry points and (optionally) debug information.
        {
            std::ofstream output(options.Output, std::ios::binary);

            if (!output) {
                std::cerr << "ce_scriptc: cannot open output file: "
                          << options.Output.string() << '\n';
                engine->ShutDownAndRelease();
                return 1;
            }

            CE::Scripting::Impl::ByteCodeWriter writer(output);

            const int save_result = module->SaveByteCode(
                &writer.GetByteCodeSink(),
                !options.Debug
            );

            if (save_result < 0) {
                std::cerr << "ce_scriptc: failed to serialize AngelScript bytecode\n";
                engine->ShutDownAndRelease();
                return 1;
            }

            if (options.Debug) {
                writer.SetDebugSymbols(importer.GetGeneratedSymbols());

                for (const auto& section : sections) {
                    CE::Scripting::Impl::ScriptSectionInfo info;
                    info.Name = section.Name;
                    info.GeneratedSource = section.Code;
                    info.Source = section.Source;

                    if (!writer.AddSection(std::move(info))) {
                        std::cerr << "ce_scriptc: failed to add script section '"
                                  << section.Name << "'\n";
                        engine->ShutDownAndRelease();
                        return 1;
                    }
                }
            }

            const std::string entry_point = importer.GetGeneratedEntrypoint("main");
            const std::string update_entry_point = importer.GetGeneratedEntrypoint("update");
            const std::string imgui_entry_point = importer.GetGeneratedEntrypoint("imgui");

            if (!entry_point.empty()) {
                writer.AddEntryPoint("main", entry_point);
            }

            if (!update_entry_point.empty()) {
                writer.AddEntryPoint("update", update_entry_point);
            }

            if (!imgui_entry_point.empty()) {
                writer.AddEntryPoint("imgui", imgui_entry_point);
            }

            if (!writer.Write()) {
                std::cerr << "ce_scriptc: failed to write CEBYC output\n";
                engine->ShutDownAndRelease();
                return 1;
            }
        }

        engine->ShutDownAndRelease();

        if (options.Verbose) {
            std::cout << "Compilation successful\n"
                      << "Wrote: " << options.Output.string() << '\n';
        }

        return 0;
    }
}

int main(int argc, char* argv[]) {
    Options options;

    if (!ParseArguments(argc, argv, options)) {
        PrintUsage(std::cerr);
        return 2;
    }

    CECommon::SetDebugLogging(options.Verbose);

    if (options.ShowHelp) {
        PrintUsage(std::cout);
        return 0;
    }

    if (options.ShowVersion) {
        PrintVersion();
        return 0;
    }

    return Compile(options);
}
